/**
 * ld-band-video — the landing "We provide a wide range of solutions…" band: a Vimeo background
 * player (embed passthrough, one 16:9 id on every device) under one centred white line, with the
 * decorative line art (CSS ::before). The slim mobile divider bar that precedes it on live
 * (canon .bar.bar-mobile-slim) is generated by the block (variant `bare` = no bar).
 * Decode tier: template-slotted. Authoring (one row, one cell, flat siblings):
 *   <p><a href="https://player.vimeo.com/video/…">title</a></p>  the player
 *   <p>…</p>  the band text (a sibling may author an <h2> — role kept)
 * Editability (EW1–EW10): the text nodes are MOVED into the generated .e-inner.
 * @ew-exempt vimeo-embed — the player.vimeo.com link becomes the background iframe
 *   (embed passthrough; the authored link text is the iframe title)
 */
export default function decorate(block) {
  const video = document.createElement('div');
  video.className = 'ld-band-video-video';
  video.setAttribute('role', 'presentation');
  block.querySelectorAll('a[href*="player.vimeo.com"]').forEach((a) => {
    const frame = document.createElement('iframe');
    frame.src = a.href;
    frame.title = a.textContent.trim();
    frame.setAttribute('allow', 'autoplay; fullscreen');
    frame.setAttribute('loading', 'lazy');
    frame.tabIndex = -1;
    video.append(frame);
    (a.closest('p') || a).remove();
  });
  const inner = document.createElement('div');
  inner.className = 'e-inner';
  block.querySelectorAll(':scope > div > div > *').forEach((el) => inner.append(el));
  block.replaceChildren(video, inner);
  if (block.classList.contains('bare')) return;
  const bar = document.createElement('div');
  bar.className = 'bar bar-mobile-slim';
  bar.setAttribute('role', 'presentation');
  block.before(bar);
}
